#include "sea_nuclear_wave.hpp"
#include <cmath>
#include <cstdio>
#include <algorithm>
int main(){for(float scale:{1.f,10.f})for(float age:{1.f,5.f,20.f}){SeaNuclearWave w{0,0,0,0,true,scale};w.Advance(age);float maxerr=0,lo=1e9f,hi=-1e9f,foam=0;int neg=0,positive=0,foam_on=0,foam_off=0;for(int a=0;a<120;a++){float angle=6.2831853f*a/120;for(int i=-120;i<=120;i++){float r=std::max(.2f,w.Front()+w.sampleWidth*i/100.f);float x=r*std::cos(angle),z=r*std::sin(angle),e=.04f;auto s=EvaluateSeaNuclearWave(w,x,z);auto xp=EvaluateSeaNuclearWave(w,x+e,z),xm=EvaluateSeaNuclearWave(w,x-e,z),zp=EvaluateSeaNuclearWave(w,x,z+e),zm=EvaluateSeaNuclearWave(w,x,z-e);maxerr=std::max({maxerr,std::abs((xp.height-xm.height)/(2*e)-s.slopeX),std::abs((zp.height-zm.height)/(2*e)-s.slopeZ)});lo=std::min(lo,s.height);hi=std::max(hi,s.height);foam=std::max(foam,s.foam);if(s.height<-.01)neg++;if(s.height>.01)positive++;if(s.foam>.01f)foam_on++;else if(s.height>.5f)foam_off++;}}std::printf("scale=%.0f age=%.0f min=%g max=%g slope_error=%g foam_max=%g crest_on=%d crest_off=%d neg=%d positive=%d\n",scale,age,lo,hi,maxerr,foam,foam_on,foam_off,neg,positive);if(maxerr>.02f || !neg || !positive || !foam_on || !foam_off)return 1;}}
